function spotsFor(pano) {
  if (pano === "forest") return FOREST_SPOTS[FOREST_PICK] || FOREST_SPOTS[1];
  return SPOT_BY_PANO[pano] || [];
}
var SPOTS = IS_GATE ? SPOT_DEF : spotsFor(PANO);
if (!qs.get("look")) {
  view.lon = view.tLon = SPOTS.length ? SPOTS[0].lon : 0;
  view.lat = view.tLat = SPOTS.length ? SPOTS[0].lat : 0;
}
var spotsLayer = document.getElementById("spots");
var lineTimer = null;
function showLine(text) {
  let el = document.getElementById("pano-line");
  if (!el) {
    el = document.createElement("div");
    el.id = "pano-line";
    document.body.appendChild(el);
  }
  el.textContent = text;
  el.classList.add("on");
  clearTimeout(lineTimer);
  lineTimer = setTimeout(() => el.classList.remove("on"), 5200);
}
function readSave() {
  return JSON.parse(localStorage.getItem(SAVE_KEY) || "{}");
}
function writeSave(v) {
  localStorage.setItem(SAVE_KEY, JSON.stringify(v));
}
function syncMerit() {
  meritEl.textContent = lifeHudText();
}
